    isBalanced:{[s]
        / We use a fold (over) to track the nesting level.
        / If the level ever drops below 0, it's unbalanced.
        / If the final level is 0, it's balanced.
        res: 0;
        while[count s > 0;
            char: s 0;
            res+: (char=`(`) - (char=``)`);
            if[res < 0; return 0];
            s: s 1 # s
