/
/ @param x {int} Input integer
/ @return {int[]} The integer list
get_odd_collatz:{[x]
    / Use a while loop to generate the Collatz sequence.
    / We store the sequence in a list 's'.
    s:x;
    while[x > 1;
        x: $[x mod 2 = 0; x div 2; 3 * x + 1];
        s, x
    ];

